/*
 * Branding (logo + cover photo) for the companies created by
 * touristo/utils/seedData.js.
 *
 * Kept in one place so both the seeder and the backfill script
 * (scripts/backfill-host-branding.js) stay in sync.
 *
 * Logos are generated by ui-avatars.com (distinct brand colour +
 * initials). Covers are Pexels photos of relevant Pakistan scenery -
 * public, hotlinkable and verified to return HTTP 200.
 */

const pexels = (id, width = 1200) =>
  `https://images.pexels.com/photos/${id}/pexels-photo-${id}.jpeg?auto=compress&cs=tinysrgb&w=${width}`;

const avatar = (name, background) =>
  `https://ui-avatars.com/api/?name=${name.replace(
    / /g,
    '+'
  )}&background=${background}&color=fff&size=256&bold=true`;

const HOST_BRANDING = {
  'Pakistan Travel Experts': {
    logo_url: avatar('Pakistan Travel Experts', '1d4ed8'),
    cover_image_url: pexels(27468879),
  },
  'Northern Adventures': {
    logo_url: avatar('Northern Adventures', '0d9488'),
    cover_image_url: pexels(33837898),
  },
  'Hunza Valley Tours': {
    logo_url: avatar('Hunza Valley Tours', '7c3aed'),
    cover_image_url: pexels(31839253),
  },
  'Swat Tourism': {
    logo_url: avatar('Swat Tourism', '15803d'),
    cover_image_url: pexels(37385405),
  },
  'Coastal Adventures': {
    logo_url: avatar('Coastal Adventures', '0369a1'),
    cover_image_url: pexels(12180798),
  },
  'Mountain Expeditions': {
    logo_url: avatar('Mountain Expeditions', '334155'),
    cover_image_url: pexels(33784883),
  },
  'Historical Heritage Tours': {
    logo_url: avatar('Historical Heritage Tours', 'b45309'),
    cover_image_url: pexels(6255712),
  },
  'Naran Kaghan Explorer': {
    logo_url: avatar('Naran Kaghan Explorer', '0f766e'),
    cover_image_url: pexels(32889687),
  },
  'Babusar Top Adventures': {
    logo_url: avatar('Babusar Top Adventures', 'be123c'),
    cover_image_url: pexels(38667203),
  },
};


/*
 * The cover photos the first seed shipped. A host cover that still points
 * at one of these is treated as "not custom" and safe to replace.
 */
const LEGACY_HOST_COVER_IDS = [
  '1506905925346-21bda4d32df4',
  '1464822759023-fed622ff2c3b',
  '1470071459604-3b5ec3a7fe05',
  '1439066615861-d1af74d74000',
  '1507525428034-b723cf961d3e',
  '1483728642387-6c3bdd6c93e5',
  '1564507592333-c60657eea523',
  '1441974231531-c6227db76b6e',
  '1519681393784-d120267933ba'
];

function isLegacyHostCover(image) {
  if (typeof image !== 'string' || image.trim() === '') {
    return true;
  }

  return LEGACY_HOST_COVER_IDS.some(id => image.includes(id));
}

const getHostBranding = (companyName) =>
  HOST_BRANDING[companyName] || { logo_url: null, cover_image_url: null };

module.exports = {
  HOST_BRANDING,
  LEGACY_HOST_COVER_IDS,
  isLegacyHostCover,
  getHostBranding
};
